// Merge fb_settings + fb_secrets into one config item (same pattern as WF4).
const cfgRaw = $('Fetch FB Config').first().json;
const tokRaw = $('Fetch FB Token').first().json;
const cfg = Array.isArray(cfgRaw) ? cfgRaw[0] : cfgRaw;
const tok = Array.isArray(tokRaw) ? tokRaw[0] : tokRaw;
return [{ json: {
  page_id: (cfg && cfg.fb_page_id) || '',
  graph: (cfg && cfg.fb_graph_version) || 'v25.0',
  token: (tok && tok.value) || ''
} }];

// Join Supabase queue rows to Graph engagement by FB post id, emit fb_post_metrics rows.
// Queue rows carry page_permalink like https://www.facebook.com/{page}_{post}; the tail is
// the page-scoped post id, which matches published_posts ids.
// Posts missing from Graph results (e.g. >100 posts back) are skipped rather than written
// as zeros.
// 2026-06-12: views added. v25 removed the post_impressions family; the replacement is
// post_media_view (fetched via insights field expansion in the same single Graph call).
// We store views in BOTH impressions and reach — per-post reach no longer exists in v25,
// and views is the engagement-rate denominator (same convention the major social tools
// adopted). link_clicks stays null (no v25 per-post equivalent).
const graphPosts = ($json.data || []);
const byId = new Map(graphPosts.map(p => [p.id, p]));
const queue = $('Get Page-Posted (30d)').all().map(i => i.json).filter(r => r && r.id);
const rows = [];
for (const q of queue) {
  const fbId = String(q.page_permalink || '').split('/').pop();
  const g = byId.get(fbId);
  if (!g) continue;
  const insightsData = (g.insights && g.insights.data) || [];
  const mv = insightsData.find(x => x.name === 'post_media_view');
  const views = (mv && mv.values && mv.values[0] && typeof mv.values[0].value === 'number') ? mv.values[0].value : null;
  rows.push({
    post_id: q.id,
    source: 'page',
    reactions: (g.reactions && g.reactions.summary && g.reactions.summary.total_count) || 0,
    comments: (g.comments && g.comments.summary && g.comments.summary.total_count) || 0,
    shares: (g.shares && g.shares.count) || 0,
    impressions: views,
    reach: views,
    link_clicks: null
  });
}
if (rows.length === 0) {
  return [];
}
return [{ json: { rows, count: rows.length } }];

// Map page_media_view daily values to fb_page_metrics rows.
// FB quirk: end_time is the morning AFTER the measured day, so subtract one day
// to record the actual date the views happened on.
const data = ($json.data || []);
const m = data.find(x => x.name === 'page_media_view');
const vals = (m && m.values) || [];
const nowIso = new Date().toISOString();
const rows = [];
for (const v of vals) {
  if (typeof v.value !== 'number' || !v.end_time) continue;
  const d = new Date(v.end_time);
  d.setUTCDate(d.getUTCDate() - 1);
  rows.push({ metric_date: d.toISOString().slice(0, 10), views: v.value, pulled_at: nowIso });
}
if (rows.length === 0) return [];
return [{ json: { rows } }];
